    void componentPackagesAreDataOnly(){auto d=local();const auto encoded=ModulePackages::encode(d);const auto decoded=ModulePackages::decode(encoded);QCOMPARE(decoded.id,d.id);QCOMPARE(decoded.parameters.front().registerAddress,16);auto malicious=encoded;malicious["script"]="run arbitrary code";QVERIFY_EXCEPTION_THROWN(ModulePackages::decode(malicious),std::invalid_argument);malicious=encoded;malicious["implementation"]="bme280";QVERIFY_EXCEPTION_THROWN(ModulePackages::decode(malicious),std::invalid_argument);malicious=encoded;malicious["id"]="../escape";QVERIFY_EXCEPTION_THROWN(ModulePackages::decode(malicious),std::invalid_argument);malicious=encoded;malicious["maxClock"]=1e100;QVERIFY_EXCEPTION_THROWN(ModulePackages::decode(malicious),std::invalid_argument);auto overlapping=d;overlapping.parameters.push_back(d.parameters.front());overlapping.parameters.back().name="overlap";QVERIFY_EXCEPTION_THROWN(ModuleRegistry::validate(overlapping),std::invalid_argument);}
    void packageInstallAndPortableProject(){auto d=local();QFile file(temporary_.filePath("sensor.thinkcad-components.json"));QVERIFY(file.open(QIODevice::WriteOnly));file.write(QJsonDocument(QJsonObject{{"format","ThinkCad.Components"},{"version",1},{"models",QJsonArray{ModulePackages::encode(d)}}}).toJson());file.close();QCOMPARE(ModulePackages::importFile(file.fileName()),QStringList{QString::fromStdString(d.id)});QCOMPARE(ModuleRegistry::get(d.id).label,d.label);QVERIFY(ModulePackages::loadInstalled().isEmpty());SavedProject project;project.sketch.name="Sensor";project.sketch.order={"Sensor.ino"};project.sketch.files["Sensor.ino"]="void setup(){} void loop(){}";const auto id=project.circuit.addPart(PartKind::Module,300,100);project.circuit.part(id).model=d.id;project.circuit.part(id).parameters["temperature"]=26.5;project.mode=ExecutionMode::Emulation;const auto bytes=ProjectIO::serialize(project);ModuleRegistry::removeLocal(d.id);const auto restored=ProjectIO::deserialize(bytes);QCOMPARE(restored.mode,ExecutionMode::Emulation);QCOMPARE(restored.circuit.part(id).parameters.at("temperature"),26.5);QCOMPARE(ModuleRegistry::get(d.id).registers.at(0),unsigned(0x42));ModuleRegistry::removeLocal(d.id);auto invalid=QJsonDocument::fromJson(bytes).object();invalid["files"]=QJsonArray{};QVERIFY_EXCEPTION_THROWN(ProjectIO::deserialize(QJsonDocument(invalid).toJson()),std::runtime_error);QVERIFY(!ModuleRegistry::definitions().contains(d.id));QFile::remove(file.fileName());QDir(ModulePackages::directory()).removeRecursively();}
